def root_prefix(lang: str) -> str:
    return "" if lang == "en" else "../"


def page_link(lang: str, page: str) -> str:
    return f"{page}.html"


def language_menu(lang: str) -> str:
    links = []
    for code, item in LANGUAGES.items():
        if code == "en":
            href = "index.html" if lang == "en" else "../index.html"
        else:
            href = f"{code}/index.html" if lang == "en" else f"../{code}/index.html"
        current = ' aria-current="page"' if code == lang else ""
        links.append(f'<a href="{href}" hreflang="{code}"{current}>{item["name"]}</a>')
    return f'<details class="language"><summary aria-label="Language">{LANGUAGES[lang]["short"]} ▾</summary><div class="language-menu">{"".join(links)}</div></details>'


def head(lang: str, title: str, description: str, prefix: str) -> str:
    return f'''<!doctype html>
<html lang="{lang}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#F1EEE8">
  <meta name="description" content="{description}">
  <meta property="og:type" content="website">
  <meta property="og:title" content="{title}">
  <meta property="og:description" content="{description}">
  <meta property="og:image" content="https://mehmetsancaktutan.github.io/icindekiler-site/social-preview.png">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{title}">
  <meta name="twitter:description" content="{description}">
  <meta name="twitter:image" content="https://mehmetsancaktutan.github.io/icindekiler-site/social-preview.png">
  <link rel="icon" href="{prefix}logo.png">
  <link rel="stylesheet" href="{prefix}styles.css">
  <title>{title}</title>
</head>'''


def nav(lang: str, document: bool = False) -> str:
    t = LANGUAGES[lang]
    prefix = root_prefix(lang)
    home = "index.html" if lang == "en" else "index.html"
    if document:
        links = f'<a href="{home}">{t["back"]}</a>'
    else:
        links = f'<a href="#how">{t["nav_how"]}</a><a href="privacy.html">{t["nav_privacy"]}</a>'
    return f'''<nav class="nav">
      <a class="brand" href="{home}"><img src="{prefix}logo.png" alt="Yuppa"><span>Yuppa</span></a>
      <div class="nav-links">{links}{language_menu(lang)}</div>
    </nav>'''


def footer(lang: str) -> str:
    t = LANGUAGES[lang]
    return f'''<footer class="footer">
      <small>© 2026 {t["copyright"]}</small>
      <div class="footer-links"><a href="privacy.html">{t["privacy"]}</a><a href="terms.html">{t["terms"]}</a><a href="support.html">{t["support"]}</a><a href="mailto:{EMAIL}">{EMAIL}</a></div>
    </footer>'''


def landing(lang: str) -> str:
    t = LANGUAGES[lang]
    prefix = root_prefix(lang)
    features = "".join(f'<article class="feature"><div class="feature-icon">{icon}</div><h3>{title}</h3><p>{copy}</p></article>' for icon, title, copy in t["features"])
    privacy_points = "".join(f'<div class="privacy-item"><span class="check">✓</span><span>{point}</span></div>' for point in t["privacy_points"])
    return head(lang, t["title"], t["description"], prefix) + f'''
<body>
  <div class="shell">{nav(lang)}
    <main>
      <section class="hero">
        <div class="hero-copy-area"><div class="eyebrow">{t["eyebrow"]}</div><h1>{t["headline"]}</h1><p class="hero-copy">{t["hero"]}</p>
          <div class="actions"><a class="button" href="{APP_STORE_URL}" target="_blank" rel="noopener noreferrer" aria-label="{t["appstore"]}"> {t["appstore"]}</a><span class="button" aria-label="{t["googleplay"]}">▶ {t["googleplay"]}</span></div><div class="microcopy">{t["availability"]}</div>
        </div>
        <div class="phone-stage" aria-label="Yuppa app preview"><div class="blob"></div>
          <div class="floating-card one"><b>{t["float_1"]}</b><span>{t["float_1_sub"]}</span></div>
          <div class="phone"><div class="phone-screen"><div class="dynamic-island"></div><div class="screen-kicker">{t["screen_kicker"]}</div><div class="screen-title">{t["screen_title"]}</div><div class="scan-card"><div class="product-art" aria-hidden="true">🥣</div><div class="score-row"><div class="score">82</div><div class="score-copy"><strong>{t["screen_score"]}</strong><span>{t["screen_evidence"]}</span></div></div><div class="pills"><span class="pill">{t["screen_pill_1"]}</span><span class="pill">{t["screen_pill_2"]}</span></div></div></div></div>
          <div class="floating-card two"><b>{t["float_2"]}</b><span>{t["float_2_sub"]}</span></div>
        </div>
      </section>
      <section class="section" id="how"><div class="section-head"><div class="eyebrow">{t["features_eye"]}</div><h2>{t["features_title"]}</h2><p class="section-lead">{t["features_lead"]}</p></div><div class="feature-grid">{features}</div></section>
      <section class="section"><div class="privacy-band"><div><div class="eyebrow" style="color:#e7b780">{t["privacy_eye"]}</div><h2>{t["privacy_title"]}</h2><p>{t["privacy_copy"]}</p><a class="button" style="background:#fff;color:#173f21;border-color:#fff" href="privacy.html">{t["privacy_cta"]} →</a></div><div class="privacy-list">{privacy_points}</div></div><p class="disclaimer">{t["notice"]}</p></section>
    </main>{footer(lang)}
  </div><script src="{prefix}site.js"></script>
</body></html>'''


